	if code != 3 || stdout != "" {
		t.Errorf("exit = %d, stdout = %q; want 3 and nothing on stdout", code, stdout)
	}
}

func TestFrequencyOrderAndNulls(t *testing.T) {
	path := writeCSV(t, "v\nb\na\nB\nc\na\nb\nNA\n")
